package kernels

// gemm32 is the float32 GEMM on the 4x16 vector kernel (gemmMicro4x16VXE in
// sum_s390x.s, generated by go-asmgen; see asmgen/s390x/gen.go). Its VFMASB is
// the vector-enhancements facility 1 (z14): without it there is none, and
// float32 products are computed in float64.
var gemm32 = newGemm32(useVXE)

func newGemm32(vxe bool) *gemmKernel[float32] {
	if !vxe {
		return nil
	}
	return &gemmKernel[float32]{mr: 4, nr: 16, micro: gemmMicro32}
}

// gemmMicro32 adds the 4 x 16 tile sum_p pa[p*4..]*pb[p*16..] into the C block
// at dst[0:], whose rows are ldc apart. pa, pb hold at least kc*4 and kc*16
// packed (zero-padded) floats; dst has at least 3*ldc + 16 elements.
func gemmMicro32(kc int, pa, pb, dst []float32, ldc int) {
	_, _, _ = pa[kc*4-1], pb[kc*16-1], dst[3*ldc+15] // the kernel's whole reach
	gemmMicro4x16VXE(kc, &pa[0], &pb[0], &dst[0], ldc)
}

